def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    # Last few rounds
    last_opp = opp[-1]
    last_my = my[-1]

    # Count recent opponent defections
    k = min(10, n)
    recent_opp = opp[-k:]
    recent_d = 0
    for a in recent_opp:
        if a == 'D':
            recent_d += 1
    recent_rate = recent_d / k

    # Detect long mutual cooperation streak
    cc_streak = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'C' and opp[i] == 'C':
            cc_streak += 1
        else:
            break

    # Endgame: last round, grab if opponent won't punish
    if n >= 100:
        return 'D'

    # If we have a strong mutual cooperation streak, preserve it,
    # but take the final-round bonus when safe.
    if cc_streak >= 3:
        # Probe very rarely to see if opponent is exploitable
        if recent_rate == 0 and n % 17 == 0 and n < 95:
            return 'D'
        return 'C'

    # Opening: cooperate to establish mutual cooperation
    if n < 4:
        return 'C'

    # Strong retaliation if opponent defecting heavily
    if recent_rate >= 0.6:
        return 'D'

    if last_opp == 'D':
        # Opponent defected. Short punishment, then forgive.
        # If we just defected too, consider repair.
        if last_my == 'D':
            # Check how long mutual defection has been going
            dd_streak = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    dd_streak += 1
                else:
                    break
            # Break defection spiral
            if dd_streak >= 2:
                return 'C'
            return 'D'
        else:
            # We cooperated, opponent defected. Punish once.
            # But if opponent rarely defects, occasionally forgive.
            if recent_rate <= 0.2 and rng.random() < 0.3:
                return 'C'
            return 'D'

    # Opponent cooperated last.
    if last_my == 'D':
        # We defected, they cooperated. Return to cooperation to rebuild.
        return 'C'

    # Both cooperated. Predominantly keep cooperating.
    # Rare opportunistic probe only when opponent looks non-punishing
    if n >= 10 and recent_rate == 0:
        # Check if opponent has ever punished our defections
        punished = 0
        my_d = 0
        for i in range(1, n):
            if my[i - 1] == 'D':
                my_d += 1
                if opp[i] == 'D':
                    punished += 1
        if my_d == 0:
            # Never tested; try a probe very rarely
            if n % 23 == 0:
                return 'D'
        else:
            if punished * 4 < my_d:
                # Opponent rarely punishes: exploit occasionally
                if n % 13 == 0:
                    return 'D'
            # Otherwise stay cooperative
        return 'C'

    # If opponent mostly cooperated but a bit mixed, maintain C
    if recent_rate <= 0.3:
        return 'C'

    # Fallback
    return 'C'
